"use strict";(globalThis.webpackChunkphysical_ai_humanoid_robotics_textbook=globalThis.webpackChunkphysical_ai_humanoid_robotics_textbook||[]).push([[142],{9508:i=>{i.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"tutorialSidebar":[{"type":"link","href":"/Physical-AI-Humanoid-Robotics-Textbook--Hackathon-01/intro","label":"Welcome to Physical AI & Humanoid Robotics","docId":"intro","unlisted":false},{"type":"category","label":"Foundation","items":[{"type":"link","href":"/Physical-AI-Humanoid-Robotics-Textbook--Hackathon-01/foundation/01-intro-physical-ai","label":"1. Introduction to Physical AI","docId":"foundation/01-intro-physical-ai","unlisted":false},{"type":"link","href":"/Physical-AI-Humanoid-Robotics-Textbook--Hackathon-01/foundation/02-humanoid-architecture","label":"2. Humanoid Architecture","docId":"foundation/02-humanoid-architecture","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"Module 1: ROS 2","items":[{"type":"link","href":"/Physical-AI-Humanoid-Robotics-Textbook--Hackathon-01/module-1-ros2/03-intro-ros2","label":"3. Introduction to ROS 2","docId":"module-1-ros2/03-intro-ros2","unlisted":false},{"type":"link","href":"/Physical-AI-Humanoid-Robotics-Textbook--Hackathon-01/module-1-ros2/04-nodes-topics","label":"4. Nodes, Topics, Messages","docId":"module-1-ros2/04-nodes-topics","unlisted":false},{"type":"link","href":"/Physical-AI-Humanoid-Robotics-Textbook--Hackathon-01/module-1-ros2/05-services-actions","label":"5. Services and Actions","docId":"module-1-ros2/05-services-actions","unlisted":false},{"type":"link","href":"/Physical-AI-Humanoid-Robotics-Textbook--Hackathon-01/module-1-ros2/06-system-integration","label":"6. System Integration","docId":"module-1-ros2/06-system-integration","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"Module 2: Digital Twin","items":[{"type":"link","href":"/Physical-AI-Humanoid-Robotics-Textbook--Hackathon-01/module-2-digital-twin/07-intro-digital-twins","label":"7. Introduction to Digital Twins","docId":"module-2-digital-twin/07-intro-digital-twins","unlisted":false},{"type":"link","href":"/Physical-AI-Humanoid-Robotics-Textbook--Hackathon-01/module-2-digital-twin/08-gazebo","label":"8. Gazebo Simulation","docId":"module-2-digital-twin/08-gazebo","unlisted":false},{"type":"link","href":"/Physical-AI-Humanoid-Robotics-Textbook--Hackathon-01/module-2-digital-twin/09-unity","label":"9. Unity Simulation","docId":"module-2-digital-twin/09-unity","unlisted":false},{"type":"link","href":"/Physical-AI-Humanoid-Robotics-Textbook--Hackathon-01/module-2-digital-twin/10-sim-to-real","label":"10. Sim-to-Real Transfer","docId":"module-2-digital-twin/10-sim-to-real","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"Module 3: NVIDIA Isaac","items":[{"type":"link","href":"/Physical-AI-Humanoid-Robotics-Textbook--Hackathon-01/module-3-nvidia-isaac/11-intro-isaac","label":"11. Introduction to Isaac","docId":"module-3-nvidia-isaac/11-intro-isaac","unlisted":false},{"type":"link","href":"/Physical-AI-Humanoid-Robotics-Textbook--Hackathon-01/module-3-nvidia-isaac/12-isaac-sim","label":"12. Isaac Sim","docId":"module-3-nvidia-isaac/12-isaac-sim","unlisted":false},{"type":"link","href":"/Physical-AI-Humanoid-Robotics-Textbook--Hackathon-01/module-3-nvidia-isaac/13-isaac-ros","label":"13. Isaac ROS","docId":"module-3-nvidia-isaac/13-isaac-ros","unlisted":false},{"type":"link","href":"/Physical-AI-Humanoid-Robotics-Textbook--Hackathon-01/module-3-nvidia-isaac/14-isaac-gym","label":"14. Isaac Gym","docId":"module-3-nvidia-isaac/14-isaac-gym","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"Module 4: VLA Capstone","items":[{"type":"link","href":"/Physical-AI-Humanoid-Robotics-Textbook--Hackathon-01/module-4-vla/15-intro-vla","label":"15. Introduction to VLA","docId":"module-4-vla/15-intro-vla","unlisted":false},{"type":"link","href":"/Physical-AI-Humanoid-Robotics-Textbook--Hackathon-01/module-4-vla/16-vision-systems","label":"16. Vision Systems","docId":"module-4-vla/16-vision-systems","unlisted":false},{"type":"link","href":"/Physical-AI-Humanoid-Robotics-Textbook--Hackathon-01/module-4-vla/17-llm-action-planning","label":"17. LLM Action Planning","docId":"module-4-vla/17-llm-action-planning","unlisted":false},{"type":"link","href":"/Physical-AI-Humanoid-Robotics-Textbook--Hackathon-01/module-4-vla/18-capstone","label":"18. Capstone Integration","docId":"module-4-vla/18-capstone","unlisted":false}],"collapsed":true,"collapsible":true}]},"docs":{"foundation/01-intro-physical-ai":{"id":"foundation/01-intro-physical-ai","title":"Chapter 1: Introduction to Physical AI","description":"Learning Objectives","sidebar":"tutorialSidebar"},"foundation/02-humanoid-architecture":{"id":"foundation/02-humanoid-architecture","title":"Chapter 2: Humanoid Robot Architecture Overview","description":"Learning Objectives","sidebar":"tutorialSidebar"},"intro":{"id":"intro","title":"Welcome to Physical AI & Humanoid Robotics","description":"Welcome to the Physical AI & Humanoid Robotics Textbook \u2014 your comprehensive guide to understanding how artificial intelligence meets physical embodiment in robotics.","sidebar":"tutorialSidebar"},"module-1-ros2/03-intro-ros2":{"id":"module-1-ros2/03-intro-ros2","title":"Chapter 3: What is ROS 2 and Why It Matters","description":"Learning Objectives","sidebar":"tutorialSidebar"},"module-1-ros2/04-nodes-topics":{"id":"module-1-ros2/04-nodes-topics","title":"Chapter 4: ROS 2 Core Concepts - Nodes, Topics, and Messages","description":"Learning Objectives","sidebar":"tutorialSidebar"},"module-1-ros2/05-services-actions":{"id":"module-1-ros2/05-services-actions","title":"Chapter 5: ROS 2 Services and Actions","description":"Learning Objectives","sidebar":"tutorialSidebar"},"module-1-ros2/06-system-integration":{"id":"module-1-ros2/06-system-integration","title":"Chapter 6: ROS 2 System Integration for Humanoids","description":"Learning Objectives","sidebar":"tutorialSidebar"},"module-2-digital-twin/07-intro-digital-twins":{"id":"module-2-digital-twin/07-intro-digital-twins","title":"Chapter 7: Introduction to Digital Twins","description":"Imagine testing a humanoid robot\'s ability to climb stairs\u2014but if it falls, there\'s no expensive hardware damage, no safety risks, and no downtime. You simply reset the simulation and try again. This is the power of digital twins: virtual replicas of physical robots that allow us to develop, test, and validate robotic systems in a safe, cost-effective, and repeatable way.","sidebar":"tutorialSidebar"},"module-2-digital-twin/08-gazebo":{"id":"module-2-digital-twin/08-gazebo","title":"Chapter 8: Gazebo Simulation for Humanoid Robots","description":"You\'ve designed a bipedal walking controller for your humanoid robot. It should work\u2014the math checks out, the PID gains are tuned, and the trajectory looks smooth in your visualization. But will the robot actually walk? And more importantly, will it fall over?","sidebar":"tutorialSidebar"},"module-2-digital-twin/09-unity":{"id":"module-2-digital-twin/09-unity","title":"Chapter 9: Unity for Perception and Interaction","description":"Your humanoid robot\'s object detection system works flawlessly in Gazebo\u2014detecting simple geometric shapes with 95% accuracy. But when you deploy it on the physical robot in a cluttered living room with varied lighting, performance plummets to 60%. The problem? Your AI model was trained on unrealistic, oversimplified visual data.","sidebar":"tutorialSidebar"},"module-2-digital-twin/10-sim-to-real":{"id":"module-2-digital-twin/10-sim-to-real","title":"Chapter 10: Simulation-to-Real Transfer","description":"You\'ve spent weeks perfecting your humanoid\'s walking controller in Gazebo. In simulation, it strides confidently across virtual terrain, maintaining perfect balance. Excited, you deploy the same controller on your physical robot. It takes two steps\u2014and crashes to the floor.","sidebar":"tutorialSidebar"},"module-3-nvidia-isaac/11-intro-isaac":{"id":"module-3-nvidia-isaac/11-intro-isaac","title":"Chapter 11: Introduction to NVIDIA Isaac Platform","description":"You\'ve trained your humanoid\'s object detection model in Unity with 10,000 synthetic images. It works well in simulation, but when deployed on the physical robot, it\'s painfully slow\u2014processing only 5 frames per second instead of the required 30 FPS for real-time navigation. The robot hesitates, stutters, and occasionally bumps into obstacles it detected too late.","sidebar":"tutorialSidebar"},"module-3-nvidia-isaac/12-isaac-sim":{"id":"module-3-nvidia-isaac/12-isaac-sim","title":"Chapter 12: Isaac Sim - GPU-Accelerated Robot Simulation","description":"You need to test your humanoid\'s navigation algorithm in 50 different warehouse layouts\u2014some with narrow aisles, others with moving obstacles, some well-lit, others dimly lit. In Gazebo, running one test takes 10 minutes (slower than real-time for complex scenes). Testing all 50 layouts would take 8+ hours of simulation time.","sidebar":"tutorialSidebar"},"module-3-nvidia-isaac/13-isaac-ros":{"id":"module-3-nvidia-isaac/13-isaac-ros","title":"Chapter 13: Isaac ROS - GPU-Accelerated Perception","description":"Your humanoid robot\'s camera captures images at 30 FPS, but your object detection node processes them at only 8 FPS on the CPU. The robot sees the world in slow motion\u2014by the time it detects an obstacle, it\'s already too close. You need real-time perception: process every frame as it arrives, with minimal latency.","sidebar":"tutorialSidebar"},"module-3-nvidia-isaac/14-isaac-gym":{"id":"module-3-nvidia-isaac/14-isaac-gym","title":"Chapter 14: Isaac Gym - Reinforcement Learning at Scale","description":"You want to teach a humanoid robot to walk using reinforcement learning (RL). Traditional RL requires millions of steps\u2014a single physical robot would need to walk for months continuously (and fall thousands of times) to learn. Even in simulation, training one robot at a time on a CPU would take weeks.","sidebar":"tutorialSidebar"},"module-4-vla/15-intro-vla":{"id":"module-4-vla/15-intro-vla","title":"Chapter 15: Introduction to Vision-Language-Action Systems","description":"Imagine telling your humanoid robot: \\"Bring me the book on the table.\\" The robot looks around, identifies the table, locates the book among other objects, walks over, picks it up, and hands it to you. No programming, no pre-defined waypoints, no hardcoded object detectors\u2014just natural language.","sidebar":"tutorialSidebar"},"module-4-vla/16-vision-systems":{"id":"module-4-vla/16-vision-systems","title":"Chapter 16: Vision Systems for Humanoid VLA","description":"You tell your humanoid robot: \\"Pick up the red cup on the table.\\" The robot looks at the table, identifies multiple objects (book, laptop, cup, lamp), distinguishes the cup from other objects, recognizes it\'s red (not the blue cup next to it), estimates its 3D position, and reaches for it. All of this happens because of vision systems\u2014the robot\'s ability to see and understand the world.","sidebar":"tutorialSidebar"},"module-4-vla/17-llm-action-planning":{"id":"module-4-vla/17-llm-action-planning","title":"Chapter 17: LLM-Based Action Planning for Humanoids","description":"You tell your humanoid robot fetch plates from the cabinet, place them on the table, fetch utensils, arrange them properly, fetch glasses, and so on. Traditional robotics would require hard-coding every step. With Large Language Models (LLMs), the robot can reason about the task and generate a plan autonomously.","sidebar":"tutorialSidebar"},"module-4-vla/18-capstone":{"id":"module-4-vla/18-capstone","title":"Chapter 18: Capstone - Building a Complete VLA Humanoid System","description":"You\'ve learned ROS 2 communication, digital twin simulation, NVIDIA Isaac acceleration, vision systems, and LLM-based planning. Now it\'s time to integrate everything into a complete humanoid robot system that can understand natural language, perceive the environment, and execute complex tasks autonomously.","sidebar":"tutorialSidebar"}}}}')}}]);